// Swift port of supabase/functions/_shared/gameRules.ts — the canonical rules.
// The server stays authoritative; this engine drives local play, optimistic
// online moves and the AI. Parity with the TypeScript engine is enforced by
// ParityTests, which replay vectors generated by scripts/gen-parity-vectors.ts.

public enum Player: String, Codable, Sendable, Hashable, CaseIterable {
    case x = "X"
    case o = "O"

    public var opponent: Player { self == .x ? .o : .x }
}

public enum ViewMode: String, Codable, Sendable, Hashable {
    case flat = "2D"
    case cube = "3D"
}

public typealias Board = [Player?]

public struct LayerResult: Codable, Sendable, Hashable {
    public var winner: Player?
    public var line: [Int]?

    public init(winner: Player? = nil, line: [Int]? = nil) {
        self.winner = winner
        self.line = line
    }
}

/// A line of cells that wins when one player holds all of them.
public struct BoardLine: Sendable {
    public let cells: [Int]
    /// Cross-layer lines end the match outright, so the AI weights them higher.
    public let cross: Bool
}

/// Every line on the board plus per-cell lookups, built once per config.
public struct LineIndex: Sendable {
    public let all: [BoardLine]
    /// Cell index -> how many lines pass through it; used for move ordering.
    public let weightByCell: [Int]
}

public struct GameRulesConfig: Sendable, Equatable {
    public let size: Int
    public let viewMode: ViewMode
    public let winLength: Int
    public let layerCount: Int
    public let matchWinThreshold: Int
    public let cellCount: Int
    public let cellsPerLayer: Int
    public let is3D: Bool
    /// Row, column and diagonal lines of each layer, indexed by layer.
    public let layerLines: [[[Int]]]
    /// Lines through the stack. Empty unless the board is 3D and larger than 1.
    public let crossLayerLines: [[Int]]
    public let lineIndex: LineIndex

    /// Boards are 1x1(x1) through 8x8(x8); anything else is rejected.
    public init?(size: Int, viewMode: ViewMode) {
        guard (1...8).contains(size) else { return nil }
        let is3D = viewMode == .cube
        self.size = size
        self.viewMode = viewMode
        self.is3D = is3D
        winLength = size
        layerCount = is3D ? size : 1
        cellsPerLayer = size * size
        cellCount = is3D ? size * size * size : size * size
        matchWinThreshold = is3D && size > 1 ? size - 1 : 0

        let cellsPerLayer = size * size
        let layerLines = (0..<layerCount).map { Self.makeLayerLines(size: size, offset: $0 * cellsPerLayer) }
        let crossLines = is3D && size > 1 ? Self.makeCrossLayerLines(size: size) : []
        self.layerLines = layerLines
        crossLayerLines = crossLines

        var all: [BoardLine] = crossLines.map { BoardLine(cells: $0, cross: true) }
        for lines in layerLines {
            all.append(contentsOf: lines.map { BoardLine(cells: $0, cross: false) })
        }
        var weights = [Int](repeating: 0, count: cellCount)
        for line in all {
            for cell in line.cells { weights[cell] += 1 }
        }
        lineIndex = LineIndex(all: all, weightByCell: weights)
    }

    public func index(x: Int, y: Int, z: Int) -> Int { x + y * size + z * cellsPerLayer }
    public func layerOf(_ cellIndex: Int) -> Int { cellIndex / cellsPerLayer }

    public static func == (lhs: GameRulesConfig, rhs: GameRulesConfig) -> Bool {
        lhs.size == rhs.size && lhs.viewMode == rhs.viewMode
    }

    private static func makeLayerLines(size: Int, offset: Int) -> [[Int]] {
        var lines: [[Int]] = []
        for y in 0..<size { lines.append((0..<size).map { offset + y * size + $0 }) }
        for x in 0..<size { lines.append((0..<size).map { offset + $0 * size + x }) }
        lines.append((0..<size).map { offset + $0 * size + $0 })
        lines.append((0..<size).map { offset + $0 * size + (size - 1 - $0) })
        return lines
    }

    private static func makeCrossLayerLines(size: Int) -> [[Int]] {
        let layer = size * size
        func index(_ x: Int, _ y: Int, _ z: Int) -> Int { x + y * size + z * layer }
        var lines: [[Int]] = []

        for x in 0..<size {
            for y in 0..<size { lines.append((0..<size).map { index(x, y, $0) }) }
        }
        for y in 0..<size {
            lines.append((0..<size).map { index($0, y, $0) })
            lines.append((0..<size).map { index(size - 1 - $0, y, $0) })
        }
        for x in 0..<size {
            lines.append((0..<size).map { index(x, $0, $0) })
            lines.append((0..<size).map { index(x, size - 1 - $0, $0) })
        }
        lines.append((0..<size).map { index($0, $0, $0) })
        lines.append((0..<size).map { index(size - 1 - $0, $0, $0) })
        lines.append((0..<size).map { index($0, size - 1 - $0, $0) })
        lines.append((0..<size).map { index(size - 1 - $0, size - 1 - $0, $0) })
        return lines
    }
}

public struct GameState: Sendable, Equatable {
    public var board: Board
    public var layerWinners: [LayerResult]

    public init(board: Board, layerWinners: [LayerResult]) {
        self.board = board
        self.layerWinners = layerWinners
    }

    public init(config: GameRulesConfig) {
        board = Board(repeating: nil, count: config.cellCount)
        layerWinners = Array(repeating: LayerResult(), count: config.layerCount)
    }
}

public struct LineWin: Sendable, Equatable {
    public let winner: Player?
    public let line: [Int]?
}

private func checkLinesWinner(_ board: Board, _ lines: [[Int]], winLength: Int) -> LineWin {
    for line in lines {
        if line.count < winLength { continue }
        guard let first = board[line[0]] else { continue }
        if line.allSatisfy({ board[$0] == first }) {
            return LineWin(winner: first, line: line)
        }
    }
    return LineWin(winner: nil, line: nil)
}

public func checkCrossLayerWinner(_ config: GameRulesConfig, _ board: Board) -> LineWin {
    if !config.is3D || config.size <= 1 { return LineWin(winner: nil, line: nil) }
    return checkLinesWinner(board, config.crossLayerLines, winLength: config.winLength)
}

public func checkLayerWinner(_ config: GameRulesConfig, _ board: Board, layer: Int) -> LineWin {
    checkLinesWinner(board, config.layerLines[layer], winLength: config.winLength)
}

public func checkBoardWinner(_ config: GameRulesConfig, _ board: Board) -> LineWin {
    checkLayerWinner(config, board, layer: 0)
}

public func isLayerFull(_ config: GameRulesConfig, _ board: Board, layer: Int) -> Bool {
    let offset = layer * config.cellsPerLayer
    for i in 0..<config.cellsPerLayer where board[offset + i] == nil { return false }
    return true
}

public func isValidBoardState(_ config: GameRulesConfig, _ board: Board) -> Bool {
    board.count == config.cellCount
}

public func isValidLayerResults(_ config: GameRulesConfig, _ layerWinners: [LayerResult]) -> Bool {
    layerWinners.count == config.layerCount
}

/// True while at least one empty cell sits on a layer nobody has claimed.
public func hasLegalMoves(_ config: GameRulesConfig, _ board: Board, _ layerWinners: [LayerResult]) -> Bool {
    for i in 0..<config.cellCount where board[i] == nil {
        if layerWinners[config.layerOf(i)].winner != nil { continue }
        return true
    }
    return false
}

public func legalMoves(_ config: GameRulesConfig, _ board: Board, _ layerWinners: [LayerResult]) -> [Int] {
    var moves: [Int] = []
    for i in 0..<config.cellCount where board[i] == nil {
        if layerWinners[config.layerOf(i)].winner != nil { continue }
        moves.append(i)
    }
    return moves
}

public func getTerminalWinner(_ config: GameRulesConfig, _ board: Board, _ layerWinners: [LayerResult]) -> Player? {
    guard isValidBoardState(config, board), isValidLayerResults(config, layerWinners) else { return nil }
    if config.size == 1 { return board[0] }
    if config.is3D {
        if let winner = checkCrossLayerWinner(config, board).winner { return winner }
        let xWins = layerWinners.filter { $0.winner == .x }.count
        let oWins = layerWinners.filter { $0.winner == .o }.count
        if xWins >= config.matchWinThreshold { return .x }
        if oWins >= config.matchWinThreshold { return .o }
        return nil
    }
    return checkBoardWinner(config, board).winner
}

public struct MoveResult: Sendable, Equatable {
    public let board: Board
    public let layerWinners: [LayerResult]
    public let winner: Player?
    public let draw: Bool
    public let crossLayerWinningLine: [Int]?
    public let winningLine: [Int]?
    public let isXNext: Bool
}

/// Plays `index` for whoever is next. Returns nil for any illegal move:
/// out of range, occupied, on a claimed layer, or after the game has ended.
public func applyMove(
    _ config: GameRulesConfig,
    board: Board,
    layerWinners: [LayerResult],
    index: Int,
    isXNext: Bool
) -> MoveResult? {
    guard isValidBoardState(config, board),
          isValidLayerResults(config, layerWinners),
          index >= 0, index < config.cellCount
    else { return nil }

    if getTerminalWinner(config, board, layerWinners) != nil || !hasLegalMoves(config, board, layerWinners) {
        return nil
    }

    let player: Player = isXNext ? .x : .o
    let layerIndex = config.layerOf(index)
    if board[index] != nil || layerWinners[layerIndex].winner != nil { return nil }

    var newBoard = board
    newBoard[index] = player
    var newLayerWinners = layerWinners

    func result(
        winner: Player?,
        draw: Bool = false,
        cross: [Int]? = nil,
        line: [Int]? = nil
    ) -> MoveResult {
        MoveResult(
            board: newBoard,
            layerWinners: newLayerWinners,
            winner: winner,
            draw: draw,
            crossLayerWinningLine: cross,
            winningLine: line,
            isXNext: !isXNext
        )
    }

    if config.size == 1 { return result(winner: player, line: [0]) }

    if config.is3D {
        let cross = checkCrossLayerWinner(config, newBoard)
        if let winner = cross.winner {
            return result(winner: winner, cross: cross.line, line: cross.line)
        }

        let layerResult = checkLayerWinner(config, newBoard, layer: layerIndex)
        if let winner = layerResult.winner {
            newLayerWinners[layerIndex] = LayerResult(winner: winner, line: layerResult.line)
        }

        let xWins = newLayerWinners.filter { $0.winner == .x }.count
        let oWins = newLayerWinners.filter { $0.winner == .o }.count
        if xWins >= config.matchWinThreshold { return result(winner: .x, line: layerResult.line) }
        if oWins >= config.matchWinThreshold { return result(winner: .o, line: layerResult.line) }
    } else {
        let boardResult = checkBoardWinner(config, newBoard)
        if let winner = boardResult.winner { return result(winner: winner, line: boardResult.line) }
    }

    // A full board has no legal moves, so this also covers the classic draw.
    if !hasLegalMoves(config, newBoard, newLayerWinners) { return result(winner: nil, draw: true) }
    return result(winner: nil)
}
